// Loaders for the synthetic fixture corpus under fixtures/.
//
// The corpus is generated by scripts/generate-fixtures.mjs and committed.
// Every loader validates what it reads, so a broken or tampered corpus fails
// fast instead of poisoning a downstream component.
//
// Decisions obeyed: DEC-18 (synthetic only), DEC-22 (documents + canonical
// resolutions), DEC-23 (owner + review_by), DEC-31 (one gold set, split in two),
// DEC-35 (a case belongs to a conversation), DEC-39 (later turns exist and
// are not scored), section 4.11 (taxonomy of at most 25 intents including
// 'other').
//
// A case is one turn. Both halves hold FIT_COUNT cases, and a conversation never
// straddles them.

import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';

import type { ConversationTurn } from '../coordinator/coordinator.js';

export const FIT_COUNT = 4100;
export const REPORT_COUNT = 4100;
export const INTENT_CAP = 25;

const RISK_TIERS = ['low', 'medium', 'high'] as const;
export type RiskTier = (typeof RISK_TIERS)[number];

/**
 * Where a gold half's cases came from (DEC-18).
 *
 * A closed set, so a half cannot name a provenance no reader understands and
 * no artifact can record one. 'synthetic' is the corpus this repository
 * ships and publishes every number from. 'real' is an adopter's own labelled
 * history, which lives outside the repository and never enters it.
 */
export const GOLD_SOURCES = ['synthetic', 'real'] as const;
export type GoldSource = (typeof GOLD_SOURCES)[number];

const DOC_KINDS = ['document', 'canonical_resolution'] as const;
export type DocumentKind = (typeof DOC_KINDS)[number];

export interface Taxonomy {
  version: number;
  intent_cap: number;
  intents: TaxonomyIntent[];
}

export interface TaxonomyIntent {
  id: string;
  label: string;
  risk_tier: RiskTier;
}

export interface Disposition {
  escalated: boolean;
  macro_applied: string | null;
  refund_issued: boolean;
  first_reply_minutes: number;
}

/** DEC-07: one claim of a draft, and whether the cited document truly supports it. */
export interface GoldClaim {
  text: string;
  /** The document this claim is tested against. */
  doc_id: string;
  /** Ground truth, not a judge's verdict. */
  supported: boolean;
  /**
   * How hard the claim is to refuse, or null when it is supported.
   *
   * A fit that holds only on the easy grade has measured nothing about the
   * hard one, so the grade travels with the claim and the fitting job
   * reports coverage for each.
   */
  grade: ClaimGrade | null;
}

export const CLAIM_GRADES = ['off_topic', 'absent', 'unstated_detail'] as const;
export type ClaimGrade = (typeof CLAIM_GRADES)[number];

export interface GoldTicket {
  ticket_id: string;
  source: string;
  /** The true intent, assigned by the generator. Ground truth for scoring. */
  intent: string;
  /**
   * DEC-41: what produced this case's label.
   *
   * Never `human-review`. Section 5 calls the labelling the largest single
   * cost in the plan, and `method: "human-review"` in a gold report means a
   * person read the case. A model label written there would make one field
   * mean two things, and no reader could recover which.
   *
   * Optional on read, because a corpus written before DEC-41 carries neither
   * this field nor the label beside it.
   */
  labelled_by?: string;
  /**
   * The label that labeller produced, which is what a deployment would have.
   *
   * It differs from `intent` exactly where the labeller was wrong, and that
   * difference is the agreement rate the calibration artifact records.
   */
  labelled_intent?: string;
  queue: string;
  disposition: Disposition;
  subject: string;
  body: string;
  /**
   * DEC-35: the conversation this case belongs to. Every case carries one,
   * synthetic or real: the corpus export models turns and its validator
   * requires both fields. Optional in the type because the field arrived
   * after the schema did, and the validators are where it is required.
   */
  conversation_id?: string;
  /** DEC-39: the turn this case records, counting from 1. */
  turn_number?: number;
  /**
   * DEC-37: the agent reply that answered this turn, as the next turn's
   * prompt sees it. Absent on the last turn of a conversation, which no
   * recorded reply followed.
   *
   * This mirrors `turn.approved_reply_text` in the ledger: a reply takes no
   * turn number of its own, it hangs off the turn it answered.
   */
  agent_reply?: string;
  /**
   * DEC-07: per-claim ground truth for the groundedness fit. Every synthetic
   * case carries it; a real-corpus record does not, because nobody has
   * labelled its claims.
   */
  claims?: GoldClaim[];
}

/**
 * True when a case records a first turn (DEC-39).
 *
 * Replay scores routing against an observable disposition (DEC-32). A later
 * turn's disposition reflects the whole conversation, not the decision the
 * replay is scoring, so scoring it would credit or blame the wrong choice.
 * Those cases move to the online metrics instead; none is lost.
 *
 * The filter binds every job that scores a disposition: the replay and the
 * gold report. It does not bind the calibration job, which scores a
 * prediction against the case's own intent label. A later turn carries a
 * valid label, and section 6 requires the agreement threshold to be re-fitted
 * on multi-turn data.
 *
 * An absent `turn_number` counts as a first turn. That branch is defensive
 * only: the type leaves the field optional, and every validator that admits
 * a case to a gold half or a corpus file now requires it. A record reaching
 * this function without one has bypassed a validator.
 */
export function isFirstTurn(ticket: GoldTicket): boolean {
  return ticket.turn_number === undefined || ticket.turn_number === 1;
}

/**
 * The text one case presents to a model.
 *
 * The runtime composes it in `src/intake/adapter.ts`, stores it in
 * `turn.body_text`, and reads it back as history. An offline job that
 * composed it differently would classify a prompt the runtime never sends, so
 * this is the one definition and every job calls it.
 */
export function goldCaseText(ticket: GoldTicket): string {
  return `${ticket.subject}\n\n${ticket.body}`;
}

/**
 * Prior turns of each case's conversation, keyed by ticket id (DEC-37).
 *
 * The runtime builds this shape from the ledger (`conversationHistory` in
 * src/coordinator/consumer.ts). An offline job that classifies a later turn
 * must send the same shape, or it fits a number for a prompt the runtime
 * never issues. One earlier turn contributes the customer's message and, when
 * the history recorded one, the agent reply that answered it.
 *
 * The customer entry is the whole message, subject included, because
 * `turn.body_text` holds `ticket.ticketText` and that is what the runtime
 * renders. Dropping the subject here would have quietly broken that parity.
 *
 * A case that carries no conversation is absent from the map, and callers
 * read an empty history for it.
 */
export function conversationHistories(
  tickets: readonly GoldTicket[],
): Map<string, ConversationTurn[]> {
  // Narrowed once here, so the ordering and rendering below need no
  // non-null assertion on a field the schema leaves optional.
  const byConversation = new Map<string, { ticket: GoldTicket; turnNumber: number }[]>();
  for (const ticket of tickets) {
    const { conversation_id: conversationId, turn_number: turnNumber } = ticket;
    if (conversationId === undefined || turnNumber === undefined) continue;
    const entry = { ticket, turnNumber };
    const existing = byConversation.get(conversationId);
    if (existing) existing.push(entry);
    else byConversation.set(conversationId, [entry]);
  }

  const histories = new Map<string, ConversationTurn[]>();
  for (const turns of byConversation.values()) {
    const ordered = [...turns].sort((a, b) => a.turnNumber - b.turnNumber);
    const prior: ConversationTurn[] = [];
    for (const { ticket, turnNumber } of ordered) {
      histories.set(ticket.ticket_id, [...prior]);
      prior.push({ turnNumber, author: 'customer', bodyText: goldCaseText(ticket) });
      if (ticket.agent_reply !== undefined) {
        prior.push({ turnNumber, author: 'agent', bodyText: ticket.agent_reply });
      }
    }
  }
  return histories;
}

export type GoldSplit = 'fit' | 'report';

export interface GoldFile {
  split: GoldSplit;
  source: GoldSource;
  count: number;
  tickets: GoldTicket[];
}

export interface FixtureDocument {
  doc_id: string;
  kind: DocumentKind;
  title: string;
  body: string;
  url: string;
  owner: string;
  review_by: string;
  linked_intents: string[];
}

// Resolved against this module's location so both src (vitest) and dist
// (compiled) resolve to <repo>/fixtures.
export function fixturesDir(): URL {
  return new URL('../../fixtures/', import.meta.url);
}

function readJson(relative: string): unknown {
  return JSON.parse(readFileSync(new URL(relative, fixturesDir()), 'utf8'));
}

function assert(ok: boolean, message: string): asserts ok {
  if (!ok) throw new Error(`fixture validation failed: ${message}`);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Load and validate the curated taxonomy. */
export function loadTaxonomy(): Taxonomy {
  const raw = readJson('taxonomy.json');
  assert(isRecord(raw), 'taxonomy.json is not an object');
  const intents = raw['intents'];
  assert(Array.isArray(intents), 'taxonomy.intents is not an array');
  assert(intents.length <= INTENT_CAP, `taxonomy has ${intents.length} intents, cap is ${INTENT_CAP}`);
  const seen = new Set<string>();
  for (const entry of intents) {
    assert(isRecord(entry), 'taxonomy intent is not an object');
    const id = entry['id'];
    const label = entry['label'];
    const tier = entry['risk_tier'];
    assert(typeof id === 'string' && id.length > 0, 'taxonomy intent has no id');
    assert(typeof label === 'string' && label.length > 0, `intent ${id} has no label`);
    assert(
      typeof tier === 'string' && (RISK_TIERS as readonly string[]).includes(tier),
      `intent ${id} has invalid risk_tier ${String(tier)}`,
    );
    assert(!seen.has(id), `duplicate intent id ${id}`);
    seen.add(id);
  }
  assert(seen.has('other'), "taxonomy is missing the 'other' group");
  assert(
    raw['intent_cap'] === INTENT_CAP,
    `taxonomy.intent_cap is ${String(raw['intent_cap'])}, expected ${INTENT_CAP}`,
  );
  return raw as unknown as Taxonomy;
}

/**
 * What went wrong reading a file, without quoting what the file held.
 *
 * A filesystem fault names the path, which is the operator's own and safe. A
 * parse fault is reported by kind and position only: the position is what an
 * editor needs, and the surrounding text is the customer's. Node embeds a
 * window of the input in a JSON SyntaxError, so a trailing comma in a
 * hand-written half would otherwise put a body on stderr (DEC-18).
 */
export function describeReadFault(err: unknown): string {
  if (!(err instanceof Error)) return 'unknown fault';
  if (err instanceof SyntaxError) {
    const position = /at position (\d+)/.exec(err.message)?.[1];
    const line = /line (\d+) column (\d+)/.exec(err.message);
    const where = line !== null
      ? `line ${String(line[1])} column ${String(line[2])}`
      : position !== undefined ? `position ${position}` : 'an unreported position';
    return `the file is not valid JSON, at ${where} (content withheld, DEC-18)`;
  }
  return err.message;
}

/**
 * Load one half of the gold set.
 *
 * Without a path this reads the committed synthetic corpus. With one it
 * reads the named file, so an adopter can point a job at their own labelled
 * half. That half lives outside the repository and never enters it (DEC-18);
 * the `corpus/` directory is gitignored for exactly this.
 *
 * The same rules apply either way. A path buys a different file, never a
 * weaker check, and a fault names the file it read.
 */
export function loadGoldHalf(split: GoldSplit, path?: string): GoldFile {
  if (path === undefined) return validateGoldHalf(readJson(`gold/${split}.json`), split);
  // Read and parse faults carry no path of their own: a directory gives
  // 'EISDIR: illegal operation on a directory, read' and malformed JSON gives
  // a position. Two halves reach a job by path, so an operator could not tell
  // which one was bad, or that the fault was a file at all.
  let raw: unknown;
  try {
    raw = JSON.parse(readFileSync(path, 'utf8'));
  } catch (err: unknown) {
    // Never the parse message. Node embeds a window of the input in a JSON
    // SyntaxError, and these two files hold real cases that a person
    // hand-writes, so a trailing comma puts a customer's body on stderr
    // (DEC-18). The export guards its own parse for this reason; the guard
    // belongs on every parse of real data, not on the one its author was
    // looking at.
    throw new Error(
      `cannot read the gold ${split} half at ${path}: ${describeReadFault(err)}`,
    );
  }
  return validateGoldHalf(raw, split, path);
}

/**
 * The identifiers of one half, and nothing else.
 *
 * DEC-31 needs the two halves proved disjoint, and only a caller naming both
 * can prove it. A fitting job must never open the report half's cases: the
 * structural guarantee that a report-half leak needs a code change is worth
 * more than any check. So this opens the file and validates it in full — an
 * identity taken from a file nobody validated would prove nothing — and
 * RETURNS identifiers alone. No subject and no body crosses to the caller,
 * and the returned shape has no field that could carry one. "The file is
 * never read" would be the wrong claim; this is the one that holds.
 */
export interface HalfIdentity {
  readonly split: GoldSplit;
  readonly source: GoldSource;
  readonly ticketIds: ReadonlySet<string>;
  readonly conversationIds: ReadonlySet<string>;
  /**
   * One digest per distinct claim sentence, never the sentence.
   *
   * A sentence is free text. On a real half it is the customer's own words or
   * an agent's words about their account, and a fault message reaches a
   * terminal and a CI log where DEC-18 forbids such a value. Unlike an
   * identifier there is no safe form to print, so this holds digests and the
   * sentence itself never leaves the file it was loaded from.
   */
  readonly claimDigests: ReadonlySet<string>;
  /** Drafts whose every claim is supported. */
  readonly groundedDrafts: number;
  /** Drafts carrying any claim at all, the denominator of the share above. */
  readonly draftsWithClaims: number;
}

/**
 * A stable name for the exact case set of one half.
 *
 * The disjointness check happens once, inside one job run, and then nothing
 * remembers it. So an operator could calibrate against report half B, then
 * publish against a pruned fit half A' that no longer overlaps B, and every
 * check would pass while the gate in force came from a fit that did overlap.
 * Recording this digest in both artifacts lets a reader compare the two runs
 * and see that they were proved against different sets.
 *
 * Ticket ids only, sorted, so the value does not depend on file order. Ids
 * are already identifiers; no case text enters the digest.
 */
export function halfDigest(identity: HalfIdentity): string {
  const ids = [...identity.ticketIds].sort().join('\n');
  return createHash('sha256').update(ids).digest('hex').slice(0, 16);
}

export function identityOf(half: GoldFile): HalfIdentity {
  const withClaims = half.tickets.filter((ticket) => (ticket.claims ?? []).length > 0);
  return {
    split: half.split,
    source: half.source,
    ticketIds: new Set(half.tickets.map((ticket) => ticket.ticket_id)),
    conversationIds: new Set(
      half.tickets
        .map((ticket) => ticket.conversation_id)
        .filter((id): id is string => id !== undefined),
    ),
    claimDigests: new Set(
      withClaims.flatMap((ticket) => (ticket.claims ?? []).map((claim) => claimDigest(claim.text))),
    ),
    groundedDrafts: withClaims.filter((ticket) =>
      (ticket.claims ?? []).every((claim) => claim.supported)).length,
    draftsWithClaims: withClaims.length,
  };
}

/**
 * A claim sentence's stable name.
 *
 * Always a digest, on a synthetic half as much as a real one. An identifier
 * has a safe printable form and a sentence does not, and the provenance that
 * would gate the choice is a field a caller can set wrongly. Digesting both
 * removes the decision rather than making it correctly.
 *
 * Whitespace is folded and case is dropped first, so two spellings of one
 * sentence are one sentence. Otherwise a stray double space would let the
 * same claim sit in both halves and pass the check.
 */
export function claimDigest(text: string): string {
  const normalized = text.trim().replace(/\s+/g, ' ').toLowerCase();
  return createHash('sha256').update(normalized).digest('hex').slice(0, 12);
}

export function readHalfIdentity(path: string, split: GoldSplit): HalfIdentity {
  return identityOf(loadGoldHalf(split, path));
}

/**
 * Refuse two halves that share a case or a conversation (DEC-31).
 *
 * A conversation on both sides is the subtler leak. Two turns of one thread
 * are two cases with two identifiers, so a case-level check passes, and a
 * threshold would still be fitted and published on one customer's problem.
 */
/**
 * Refuse two halves whose grounded shares are not shown to be close.
 *
 * Precision counts grounded drafts above a threshold against every draft above
 * it, so a half holding more grounded drafts is the easier one, and a
 * precision published from it reads high. The corpus this repository shipped
 * held 167 grounded drafts of 385 against 195 of 385, and the known-limits
 * section asked the reader to compensate for it.
 *
 * This is an equivalence test, not a significance test, and the difference is
 * the whole point. An earlier version refused when a two-proportion z-test
 * rejected equality. That answers "is the gap real?" when the question is "is
 * the gap small enough not to matter?", and the two come apart in both
 * directions: a 5.5 point gap over 600 drafts a side gives z = 1.91 and passed,
 * while the 7.3 point gap that motivated the check gives z = 2.02 over 385 and
 * refused. A larger corpus was allowed a larger gap. At ten thousand drafts a
 * side, a gap of 1.5 points is beyond sampling noise and could not flatter any
 * published precision, and it refused that too. Failing to reject equality was
 * never evidence of equality.
 *
 * So the halves must prove the gap SMALL. Two one-sided tests at 5 percent,
 * which is the 90 percent interval for the difference lying wholly inside the
 * margin. Sample size now works the right way round: a half too small to
 * demonstrate closeness is refused rather than passed by default, and it is
 * already too small to fit a threshold on (see minimumSupport).
 */
function assertGroundedSharesComparable(a: HalfIdentity, b: HalfIdentity): void {
  // A half with no labelled claims has no share to compare. The coverage job
  // refuses such a half itself, with a message about claims rather than about
  // balance, and that is the fault an operator should read first.
  if (a.draftsWithClaims === 0 || b.draftsWithClaims === 0) return;
  const na = a.draftsWithClaims;
  const nb = b.draftsWithClaims;
  const pa = a.groundedDrafts / na;
  const pb = b.groundedDrafts / nb;
  const difference = pb - pa;
  // Agresti-Caffo: one success and one failure added to each half before the
  // standard error, unpooled because the null here is a difference of exactly
  // the margin rather than of zero.
  //
  // The adjustment is not decoration. The textbook standard error is exactly
  // zero at a share of 0 or 1, so the interval collapses to a point and any
  // sample size passes — one draft a side "demonstrates closeness". That is
  // the trivial pass this guard replaced a significance test to remove,
  // reappearing at the edge of the range. Away from the boundary the two agree
  // to four decimal places, so nothing else moves: the committed corpus reads
  // 0.0357 either way.
  const aa = (a.groundedDrafts + 1) / (na + 2);
  const ab = (b.groundedDrafts + 1) / (nb + 2);
  const standardError = Math.sqrt((aa * (1 - aa)) / (na + 2) + (ab * (1 - ab)) / (nb + 2));
  const halfWidth = Z_90_ONE_SIDED * standardError;
  assert(
    Math.abs(difference) + halfWidth < GROUNDED_SHARE_MARGIN,
    `the halves hold ${a.groundedDrafts} and ${b.groundedDrafts} fully grounded drafts of `
      + `${na} and ${nb}, a grounded share of ${pa.toFixed(3)} against ${pb.toFixed(3)}. `
      + `The 90 percent interval for that difference reaches `
      + `${(Math.abs(difference) + halfWidth).toFixed(3)}, which does not fit inside the `
      + `${GROUNDED_SHARE_MARGIN} margin, so these halves are not shown to be equally hard `
      + 'and a precision published from one of them may read high (DEC-31).',
  );
}

/**
 * The largest grounded-share gap this repository leaves uncompensated.
 *
 * A stated margin, because "how much easier may one half be" is a judgement
 * and no test can supply it. It is anchored on the defect it replaces: the
 * halves that motivated this check differed by 7.3 points, and section 6 asked
 * the reader to allow for it. Five points is the point at which this
 * repository stops asking that of a reader.
 */
export const GROUNDED_SHARE_MARGIN = 0.05;

/** One-sided 5 percent, which is the 90 percent two-sided interval TOST reads. */
const Z_90_ONE_SIDED = 1.6448536269514722;

export function assertHalvesDisjoint(a: HalfIdentity, b: HalfIdentity): void {
  assert(a.split !== b.split, `both halves declare split ${a.split} (DEC-31)`);
  // Both halves must describe one body of data. Without this an operator can
  // pair their own fit half with a copy of the shipped report half: SYN- ids
  // never collide with real ones, so the proof passes trivially and the
  // artifact records a real fit proved against a set nobody publishes from.
  assert(
    a.source === b.source,
    `the halves declare different provenance, ${a.source} and ${b.source} (DEC-18, DEC-31)`,
  );
  for (const id of b.ticketIds) {
    assert(!a.ticketIds.has(id), `ticket ${label(id, a.source)} appears in both halves (DEC-31)`);
  }
  for (const id of b.conversationIds) {
    assert(
      !a.conversationIds.has(id),
      `conversation ${label(id, a.source)} appears in both halves (DEC-31)`,
    );
  }
  // A sentence on both sides is the leak the two checks above cannot see. Two
  // halves can hold entirely disjoint cases and still ask the judge the same
  // sentences, and then a judge that mis-reads one WORDING moves both halves
  // together.
  //
  // Wording is the limit of what this proves, and the claim must not be
  // widened past it. The digest normalises whitespace and case and then
  // hashes, so it separates sentences, never facts. The shipped corpus pairs
  // each report sentence with a paraphrase of its fit counterpart, which is a
  // deliberate choice — it keeps the two halves matched in difficulty — and it
  // means a judge that mis-reads the FACT still moves both halves together.
  // Section 6 concedes exactly that, and this check does not remove it.
  for (const digest of b.claimDigests) {
    assert(
      !a.claimDigests.has(digest),
      `claim sentence digest ${digest} appears in both halves (DEC-31)`,
    );
  }
  assertGroundedSharesComparable(a, b);
  // Last, because an overlap is the graver fault and must be the one an
  // operator is told about first. Reporting the size mismatch ahead of it
  // sent them off to trim a half before they learned of the leak.
  //
  // DEC-31 splits one gold set into two halves and publishes from the half
  // that fitted nothing. Halves of different sizes are not that split. A set
  // with an odd number of cases, or whose conversations admit no equal
  // partition, cannot be split this way at all: hold a conversation back
  // until the two sides match.
  assert(
    a.ticketIds.size === b.ticketIds.size,
    `the halves hold ${a.ticketIds.size} and ${b.ticketIds.size} cases; DEC-31 splits one `
      + 'gold set into two halves of equal size. Hold a whole conversation back from the '
      + 'larger half until the two match; a conversation may not straddle them.',
  );
}

/**
 * An identifier a fault message may carry.
 *
 * A synthetic identifier is generated and means nothing outside this
 * repository, so it is printed. A real one is a Message-ID: it embeds the
 * customer's domain and often a local part their system minted, and a fault
 * reaches a terminal and a CI log where DEC-18 says such a value may not go.
 * An operator matches the digest against their own file.
 *
 * Every fault that names a case goes through this. An earlier version applied
 * it at the two sites its author had in mind and claimed the class; the
 * validators reached from `loadGoldHalf` and from the corpus loader kept
 * printing the raw value, which is the commonest fault path of all.
 */
export function label(id: string, source: GoldSource): string {
  if (source === 'synthetic') return id;
  return `with id digest ${createHash('sha256').update(id).digest('hex').slice(0, 12)}`;
}

/**
 * Validate an unknown value as one half of the gold set.
 *
 * Split out of `loadGoldHalf` so the rules can be tested against a malformed
 * corpus without writing one to disk. Same shape as
 * `validateCalibrationArtifact`: the loader is a thin read around it.
 */
export function validateGoldHalf(raw: unknown, split: GoldSplit, fileName?: string): GoldFile {
  // Named fileName, not label: `label` is the redaction helper this function's
  // own ticket loop depends on, and shadowing it here would be silent.
  const name = fileName ?? `gold/${split}.json`;
  assert(isRecord(raw), `${name} is not an object`);
  assert(raw['split'] === split, `${name} declares split ${String(raw['split'])}`);
  const source = raw['source'];
  assert(
    typeof source === 'string' && (GOLD_SOURCES as readonly string[]).includes(source),
    `${name} declares source ${String(source)}, expected one of ${GOLD_SOURCES.join(', ')}`,
  );
  const tickets = raw['tickets'];
  assert(Array.isArray(tickets), `${name} tickets is not an array`);
  assert(tickets.length > 0, `${name} has no tickets`);
  for (const ticket of tickets) validateTicket(ticket, source as GoldSource);
  const file = raw as unknown as GoldFile;
  assert(file.count === file.tickets.length, `${name} count does not match its tickets`);
  assertConversations(file, name);
  return file;
}

/** Load both halves of the gold set and check the DEC-31 split discipline. */
export function loadGoldSet(): { fit: GoldFile; report: GoldFile } {
  const fit = loadGoldHalf('fit');
  const report = loadGoldHalf('report');
  assert(fit.count === FIT_COUNT, `fit half holds ${fit.count} tickets, expected ${FIT_COUNT}`);
  assert(report.count === REPORT_COUNT, `report half holds ${report.count} tickets, expected ${REPORT_COUNT}`);
  // One rule, one place. The real path proves the same thing through the same
  // function, so a change to what "disjoint" means reaches both.
  assertHalvesDisjoint(identityOf(fit), identityOf(report));
  return { fit, report };
}

/**
 * A case's per-claim ground truth (DEC-07).
 *
 * Optional, because a real-corpus record carries none. When present every
 * claim is checked: a supported claim names no grade, an unsupported one
 * names a known grade, and every claim cites a document. A draft with no
 * claim would give the fit a coverage of nothing over nothing.
 */
function validateClaims(ticket: Record<string, unknown>, id: string): void {
  const claims = ticket['claims'];
  if (claims === undefined) return;
  assert(Array.isArray(claims), `ticket ${id} has a claims field that is not an array`);
  assert(claims.length > 0, `ticket ${id} carries an empty claims array`);
  for (const [i, raw] of claims.entries()) {
    assert(
      typeof raw === 'object' && raw !== null && !Array.isArray(raw),
      `ticket ${id} claim ${i} is not an object`,
    );
    const claim = raw as Record<string, unknown>;
    assert(
      typeof claim['text'] === 'string' && claim['text'].length > 0,
      `ticket ${id} claim ${i} has no text`,
    );
    assert(
      typeof claim['doc_id'] === 'string' && claim['doc_id'].length > 0,
      `ticket ${id} claim ${i} cites no document`,
    );
    assert(
      typeof claim['supported'] === 'boolean',
      `ticket ${id} claim ${i} has no boolean supported flag`,
    );
    if (claim['supported'] === true) {
      assert(claim['grade'] === null, `ticket ${id} claim ${i} is supported and names a grade`);
    } else {
      assert(
        typeof claim['grade'] === 'string'
          && (CLAIM_GRADES as readonly string[]).includes(claim['grade']),
        `ticket ${id} claim ${i} is unsupported and names no known grade`,
      );
    }
  }
}

/**
 * Field-level checks shared by the synthetic gold set and any file that
 * reuses the GoldFile schema, such as the real-corpus exporter.
 *
 * Identifier-prefix rules are not checked here: they describe the shipped
 * corpus, and each consumer keeps its own. The provenance IS taken, because
 * every fault below names a case and a real identifier must be redacted
 * (DEC-18).
 */
export function validateTicketFields(
  ticket: Record<string, unknown>,
  /**
   * Required, for the reason `scoreDraft` states: a default lets a call site
   * forget it and leak a real identifier with every test still green.
   */
  source: GoldSource,
): void {
  const rawId = typeof ticket['ticket_id'] === 'string' ? ticket['ticket_id'] : '<missing>';
  const id = label(rawId, source);
  assert(typeof ticket['intent'] === 'string', `ticket ${id} has no intent`);
  assert(typeof ticket['queue'] === 'string' && ticket['queue'].length > 0, `ticket ${id} has no queue`);
  assert(typeof ticket['subject'] === 'string' && ticket['subject'].length > 0, `ticket ${id} has no subject`);
  assert(typeof ticket['body'] === 'string' && ticket['body'].length > 0, `ticket ${id} has no body`);
  validateClaims(ticket, id);
  const disposition = ticket['disposition'];
  assert(isRecord(disposition), `ticket ${id} has no disposition object`);
  assert(typeof disposition['escalated'] === 'boolean', `disposition.escalated is not boolean on ${id}`);
  assert(
    disposition['macro_applied'] === null || typeof disposition['macro_applied'] === 'string',
    `disposition.macro_applied is neither null nor string on ${id}`,
  );
  assert(typeof disposition['refund_issued'] === 'boolean', `disposition.refund_issued is not boolean on ${id}`);
  const minutes = disposition['first_reply_minutes'];
  assert(
    typeof minutes === 'number' && Number.isInteger(minutes) && minutes >= 0,
    `disposition.first_reply_minutes is not a non-negative integer on ${id}`,
  );
}

/**
 * Synthetic-corpus checks on top of the shared field rules.
 *
 * The conversation fields live here, not in `validateTicketFields`, for the
 * reason that function's own comment gives: the shared validator keeps only
 * what every consumer shares. The corpus loader checks the same two fields
 * with its own rules, because a corpus file is not a gold half and its
 * identifiers follow no prefix convention.
 */
function validateTicket(value: unknown, source: GoldSource): void {
  assert(isRecord(value), 'ticket is not an object');
  const rawId = value['ticket_id'];
  assert(typeof rawId === 'string' && rawId.length > 0, 'ticket has no ticket_id');
  // Redacted like every other fault that names a case. Cycle 2 threaded the
  // provenance into this function and applied it to what it delegates to,
  // leaving this function's own five messages raw — the same instance-not-
  // class slip the label() comment above describes.
  const id = label(rawId, source);
  // The SYN- prefixes describe the corpus this repository generates, so they
  // bind a half that claims to be it. An adopter's labelled history carries
  // their own identifiers; holding it to the generator's naming would refuse
  // every real half for a reason that says nothing about its correctness.
  if (source === 'synthetic') {
    assert(id.startsWith('SYN-'), 'ticket_id must start with SYN-');
  }
  assert(
    value['source'] === source,
    `ticket ${id} declares source ${String(value['source'])}, but its half declares ${source}`,
  );
  const conversationId = value['conversation_id'];
  assert(
    typeof conversationId === 'string' && conversationId.length > 0,
    `ticket ${id} names no conversation (DEC-35)`,
  );
  if (source === 'synthetic') {
    assert(
      conversationId.startsWith('CONV-SYN-'),
      `ticket ${id} conversation_id must start with CONV-SYN- (DEC-35)`,
    );
  }
  const turnNumber = value['turn_number'];
  assert(
    typeof turnNumber === 'number' && Number.isInteger(turnNumber) && turnNumber >= 1,
    `ticket ${id} turn_number is not a positive integer (DEC-38)`,
  );
  const reply = value['agent_reply'];
  assert(
    reply === undefined || (typeof reply === 'string' && reply.length > 0),
    `ticket ${id} agent_reply is present but empty`,
  );
  validateTicketFields(value, source);
}

/**
 * Checks that the cases of one half describe whole, well-formed
 * conversations: unique ticket ids, turns numbered 1..N with no gap and no
 * repeat, and one intent, queue and disposition per conversation.
 *
 * The last rule is what makes DEC-39 meaningful. A disposition belongs to the
 * thread, so a half that gave two turns of one thread different outcomes would
 * make "score the first turn" a different claim from case to case.
 */
function sameDisposition(a: Disposition, b: Disposition): boolean {
  return (
    a.escalated === b.escalated
    && a.macro_applied === b.macro_applied
    && a.refund_issued === b.refund_issued
    && a.first_reply_minutes === b.first_reply_minutes
  );
}

function assertConversations(file: GoldFile, name: string): void {
  const named = (id: string): string => label(id, file.source);
  const ids = new Set<string>();
  const byConversation = new Map<string, GoldTicket[]>();
  for (const ticket of file.tickets) {
    assert(
      !ids.has(ticket.ticket_id),
      `${name} repeats ticket ${label(ticket.ticket_id, file.source)}`,
    );
    ids.add(ticket.ticket_id);
    const conversationId = ticket.conversation_id ?? '';
    const existing = byConversation.get(conversationId);
    if (existing) existing.push(ticket);
    else byConversation.set(conversationId, [ticket]);
  }

  for (const [conversationId, turns] of byConversation) {
    const numbers = turns.map((turn) => turn.turn_number ?? 0).sort((a, b) => a - b);
    numbers.forEach((number, index) => {
      assert(
        number === index + 1,
        `conversation ${named(conversationId)} numbers its turns ${numbers.join(',')}, expected 1..${numbers.length}`,
      );
    });
    const first = turns.find((turn) => turn.turn_number === 1);
    assert(first !== undefined, `conversation ${named(conversationId)} has no first turn`);
    for (const turn of turns) {
      assert(
        turn.intent === first.intent && turn.queue === first.queue,
        `conversation ${named(conversationId)} changes intent or queue between turns`,
      );
      assert(
        sameDisposition(turn.disposition, first.disposition),
        `conversation ${named(conversationId)} changes its disposition between turns`,
      );
    }
    // Exactly the turns another turn follows carry a reply. The thread ends
    // without one, because the reply to the last turn is what a run would
    // produce. A missing reply on an earlier turn would silently drop the
    // agent half of the history the prompts read (DEC-37).
    //
    // This binds the generated corpus, where the reply is authored beside the
    // turn and its absence is a generator fault. It cannot bind real history:
    // whether an agent answered in writing is a fact about a mailbox, not a
    // rule a half can obey. A thread resolved by telephone records no reply,
    // and refusing it would state something false about the archive. The
    // export reports how much of each conversation it captured instead.
    if (file.source !== 'synthetic') continue;
    const lastNumber = Math.max(...numbers);
    for (const turn of turns) {
      const isLast = turn.turn_number === lastNumber;
      assert(
        (turn.agent_reply === undefined) === isLast,
        isLast
          ? `conversation ${named(conversationId)} records a reply to its last turn`
          : `conversation ${named(conversationId)} turn ${String(turn.turn_number)} has a later turn but no agent_reply`,
      );
    }
  }
}

/** Load and validate the retrieval corpus of documents and canonical resolutions. */
export function loadDocuments(): FixtureDocument[] {
  const raw = readJson('documents.json');
  assert(isRecord(raw), 'documents.json is not an object');
  const documents = raw['documents'];
  assert(Array.isArray(documents), 'documents.documents is not an array');
  assert(documents.length > 0, 'documents.json has no documents');
  const seen = new Set<string>();
  for (const entry of documents) {
    assert(isRecord(entry), 'document is not an object');
    const id = entry['doc_id'];
    assert(
      typeof id === 'string' && /^(DOC|RES)-SYN-/.test(id),
      `doc_id ${String(id)} must start with DOC-SYN- or RES-SYN-`,
    );
    assert(!seen.has(id), `duplicate doc_id ${id}`);
    seen.add(id);
    assert(
      typeof entry['kind'] === 'string' && (DOC_KINDS as readonly string[]).includes(entry['kind']),
      `document ${id} has invalid kind ${String(entry['kind'])}`,
    );
    // DEC-23: every document declares an owner and a review date.
    assert(typeof entry['owner'] === 'string' && entry['owner'].length > 0, `document ${id} has no owner`);
    const reviewBy = entry['review_by'];
    assert(typeof reviewBy === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(reviewBy), `document ${id} has no review_by date`);
    assert(!Number.isNaN(Date.parse(reviewBy)), `document ${id} review_by is not a valid date`);
    assert(typeof entry['title'] === 'string' && entry['title'].length > 0, `document ${id} has no title`);
    assert(typeof entry['body'] === 'string' && entry['body'].length > 0, `document ${id} has no body`);
    assert(typeof entry['url'] === 'string' && entry['url'].startsWith('https://'), `document ${id} url is not https`);
    assert(Array.isArray(entry['linked_intents']), `document ${id} linked_intents is not an array`);
    assert(entry['linked_intents'].length > 0, `document ${id} links no intents`);
  }
  return documents as unknown as FixtureDocument[];
}

/** Check that every referenced intent exists in the taxonomy. Callers that
 * need both corpora use this once instead of wiring loaders together. */
export function assertIntentsKnown(taxonomy: Taxonomy, documents: FixtureDocument[]): void {
  const known = new Set(taxonomy.intents.map((i) => i.id));
  for (const document of documents) {
    for (const intent of document.linked_intents) {
      assert(known.has(intent), `document ${document.doc_id} links unknown intent ${intent}`);
    }
  }
}
